"use client";

import { mergeProps } from "@base-ui/react/merge-props";
import { useRender } from "@base-ui/react/use-render";
import { Columns3Icon, XIcon } from "lucide-react";
import type { ReactElement, ReactNode } from "react";
import { cn } from "@/registry/default/lib/utils";
import { Button, type ButtonProps } from "@/registry/default/ui/button";
import {
  ContextMenu,
  ContextMenuItem,
  ContextMenuPopup,
  ContextMenuTrigger,
} from "@/registry/default/ui/context-menu";

export type AgentActionBarProps = Omit<
  useRender.ComponentProps<"div">,
  "aria-label" | "role"
> & {
  label: string;
};

/** A labelled row of session chips and a launcher. Your application places it, for example fixed to a corner. */
export function AgentActionBar({
  label,
  className,
  render,
  ...props
}: AgentActionBarProps): ReactElement {
  const defaultProps = {
    "aria-label": label,
    role: "group",
    "data-slot": "agent-action-bar",
    className: cn("flex min-w-0 items-center justify-end gap-1", className),
  };

  return useRender({
    defaultTagName: "div",
    render,
    props: mergeProps<"div">(defaultProps, props),
  });
}

const chipClassName =
  "text-muted-foreground hover:text-foreground aria-[current]:bg-accent aria-[current]:text-foreground data-popup-open:bg-accent data-popup-open:text-foreground";

export type AgentActionBarSessionProps = Omit<
  ButtonProps,
  "aria-current" | "children" | "size" | "variant"
> & {
  label: string;
  /** The session is open, for example in a panel. Sets `aria-current`. */
  active?: boolean;
  /** The session changed since the reader last saw it. Derive it with `isAgentSessionUnread`. */
  unread?: boolean;
  /** Read after the label while `unread` is set, such as “Unread”. */
  unreadLabel?: string;
  /** The close button’s accessible name. Include the session, such as “Close Plan the offsite”. */
  closeLabel?: string;
  /** Without it, the chip has no close button. */
  onClose?: () => void;
  closeOthersLabel?: string;
  /** Adds a context menu with close and close others. */
  onCloseOthers?: () => void;
};

/**
 * One open session. Props other than the ones below go to the session button, so it can be the
 * `render` of a popover trigger. The close button shows on hover and focus, and always on touch.
 */
export function AgentActionBarSession({
  label,
  active = false,
  unread = false,
  unreadLabel,
  closeLabel,
  onClose,
  closeOthersLabel,
  onCloseOthers,
  onClick,
  render,
  disabled,
  className,
  ...props
}: AgentActionBarSessionProps): ReactElement {
  const closable = Boolean(onClose && closeLabel);
  const chip = (
    <div
      data-slot="agent-action-bar-session"
      data-active={active || undefined}
      data-unread={unread || undefined}
      className={cn("relative flex min-w-0 max-w-44", className)}
    >
      <Button
        aria-current={active ? "true" : undefined}
        className={cn(
          "w-full min-w-0 justify-start",
          chipClassName,
          // The chip stays lit while the pointer is on its close button.
          closable &&
            "in-[[data-slot=agent-action-bar-session]:hover]:bg-accent pe-7 in-[[data-slot=agent-action-bar-session]:hover]:text-foreground sm:pe-6",
        )}
        disabled={disabled || (!onClick && !render)}
        onClick={onClick}
        render={render}
        size="xs"
        variant="ghost"
        {...props}
      >
        {unread && (
          <span
            aria-hidden="true"
            className="size-1.5 shrink-0 rounded-full bg-primary"
            data-slot="agent-action-bar-session-unread"
          />
        )}
        <span className="min-w-0 truncate">{label}</span>
        {unread && unreadLabel && (
          <span className="sr-only">, {unreadLabel}</span>
        )}
      </Button>
      {closable && (
        <Button
          aria-label={closeLabel}
          className={cn(
            "absolute inset-y-0 end-0 text-muted-foreground transition-opacity hover:bg-transparent hover:text-foreground motion-reduce:transition-none",
            // Fine pointers reveal close on hover or focus. Coarse pointers have no hover, so it stays.
            "pointer-fine:in-[[data-slot=agent-action-bar-session]:not(:hover):not(:focus-within)]:opacity-0",
          )}
          data-slot="agent-action-bar-session-close"
          onClick={onClose}
          size="icon-xs"
          variant="ghost"
        >
          <XIcon aria-hidden="true" />
        </Button>
      )}
    </div>
  );

  if (!onCloseOthers || !closeOthersLabel || !closable) return chip;

  return (
    <ContextMenu>
      <ContextMenuTrigger render={chip} />
      <ContextMenuPopup>
        <ContextMenuItem onClick={onClose}>
          <XIcon aria-hidden="true" />
          {closeLabel}
        </ContextMenuItem>
        <ContextMenuItem onClick={onCloseOthers}>
          <Columns3Icon aria-hidden="true" />
          {closeOthersLabel}
        </ContextMenuItem>
      </ContextMenuPopup>
    </ContextMenu>
  );
}

export type AgentActionBarLauncherProps = Omit<
  ButtonProps,
  "aria-current" | "size" | "variant"
> & {
  /** The new conversation is open. Sets `aria-current`. */
  active?: boolean;
  /** The agent’s identity mark before the label, such as a logo. It’s hidden from screen readers. */
  mark?: ReactNode;
};

/** Starts a new conversation. Its children are the label. */
export function AgentActionBarLauncher({
  active = false,
  mark,
  children,
  onClick,
  render,
  disabled,
  className,
  ...props
}: AgentActionBarLauncherProps): ReactElement {
  return (
    <Button
      aria-current={active ? "true" : undefined}
      className={cn("shrink-0", chipClassName, className)}
      data-slot="agent-action-bar-launcher"
      disabled={disabled || (!onClick && !render)}
      onClick={onClick}
      render={render}
      size="xs"
      variant="ghost"
      {...props}
    >
      {mark && (
        <span
          aria-hidden="true"
          className="flex shrink-0 items-center"
          data-slot="agent-action-bar-launcher-mark"
        >
          {mark}
        </span>
      )}
      {children}
    </Button>
  );
}

import type { ComponentProps, ReactElement } from "react";
import { cn } from "@/registry/default/lib/utils";
import type { AgentAnnouncerController } from "./hooks/use-agent-announcer";

export type AgentAnnouncerProps = Omit<
  ComponentProps<"span">,
  "children" | "role"
> & {
  announcer: AgentAnnouncerController;
};

/** The conversation's one status region. Render it once, outside the scrolling log. */
export function AgentAnnouncer({
  announcer,
  className,
  ...props
}: AgentAnnouncerProps): ReactElement {
  return (
    <span
      aria-atomic="true"
      aria-live="polite"
      data-slot="agent-announcer"
      role="status"
      className={cn("sr-only", className)}
      {...props}
    >
      {announcer.message}
    </span>
  );
}

"use client";

import { CopyIcon, EllipsisIcon, TrashIcon } from "lucide-react";
import { type ReactElement, useState } from "react";
import { cn } from "@/registry/default/lib/utils";
import {
  AlertDialog,
  AlertDialogClose,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogPopup,
  AlertDialogTitle,
} from "@/registry/default/ui/alert-dialog";
import { Button, type ButtonProps } from "@/registry/default/ui/button";
import {
  Menu,
  MenuItem,
  MenuPopup,
  MenuSeparator,
  MenuTrigger,
} from "@/registry/default/ui/menu";
import {
  Tooltip,
  TooltipPopup,
  TooltipTrigger,
} from "@/registry/default/ui/tooltip";
import type { AgentAnnouncerController } from "./hooks/use-agent-announcer";
import { copyAgentText } from "./lib/copy-agent-text";

export type AgentConversationMenuLabels = {
  /** Names the trigger and fills its tooltip. */
  menu: string;
  copyAsMarkdown: string;
  /** Announced after a successful copy. */
  copied: string;
  /** Announced when the clipboard refuses the copy. */
  copyFailed: string;
  delete: string;
  deleteTitle: string;
  deleteDescription: string;
  deleteConfirm: string;
  cancel: string;
};

export type AgentConversationMenuProps = Omit<
  ButtonProps,
  "aria-label" | "children" | "onClick" | "render" | "size" | "variant"
> & {
  labels: AgentConversationMenuLabels;
  /** The conversation as Markdown. Without it there’s no copy item; while empty, the item is disabled. */
  markdown?: string;
  /** The conversation’s announcer, or anything with `announce`. Hears the copy result once. */
  announcer: Pick<AgentAnnouncerController, "announce">;
  /** Runs after the reader confirms. Without it there’s no delete item. */
  onDelete?: () => void;
};

/** The conversation’s “…” menu: copy as Markdown, and delete behind a confirmation. */
export function AgentConversationMenu({
  labels,
  markdown,
  announcer,
  onDelete,
  className,
  ...props
}: AgentConversationMenuProps): ReactElement {
  const [confirming, setConfirming] = useState(false);

  const copy = async (): Promise<void> => {
    const copied = await copyAgentText(markdown ?? "", navigator.clipboard);
    announcer.announce(copied ? labels.copied : labels.copyFailed);
  };

  return (
    <>
      <Menu>
        <Tooltip>
          <TooltipTrigger
            render={
              <MenuTrigger
                render={
                  <Button
                    aria-label={labels.menu}
                    className={cn(
                      "text-muted-foreground hover:text-foreground data-popup-open:text-foreground",
                      className,
                    )}
                    data-slot="agent-conversation-menu"
                    size="icon-xs"
                    variant="ghost"
                    {...props}
                  />
                }
              />
            }
          >
            <EllipsisIcon aria-hidden="true" />
          </TooltipTrigger>
          <TooltipPopup>{labels.menu}</TooltipPopup>
        </Tooltip>
        <MenuPopup align="end">
          {markdown !== undefined && (
            <MenuItem disabled={!markdown} onClick={() => void copy()}>
              <CopyIcon aria-hidden="true" />
              {labels.copyAsMarkdown}
            </MenuItem>
          )}
          {markdown !== undefined && onDelete && <MenuSeparator />}
          {onDelete && (
            <MenuItem onClick={() => setConfirming(true)} variant="destructive">
              <TrashIcon aria-hidden="true" />
              {labels.delete}
            </MenuItem>
          )}
        </MenuPopup>
      </Menu>
      {onDelete && (
        <AlertDialog onOpenChange={setConfirming} open={confirming}>
          <AlertDialogPopup>
            <AlertDialogHeader>
              <AlertDialogTitle>{labels.deleteTitle}</AlertDialogTitle>
              <AlertDialogDescription>
                {labels.deleteDescription}
              </AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter>
              <AlertDialogClose render={<Button variant="ghost" />}>
                {labels.cancel}
              </AlertDialogClose>
              <Button
                onClick={() => {
                  setConfirming(false);
                  onDelete();
                }}
                variant="destructive"
              >
                {labels.deleteConfirm}
              </Button>
            </AlertDialogFooter>
          </AlertDialogPopup>
        </AlertDialog>
      )}
    </>
  );
}

"use client";

import type { ReactElement, UIEvent } from "react";
import { cn } from "@/registry/default/lib/utils";
import {
  ChatConversation,
  type ChatConversationProps,
} from "../chat/chat-conversation";
import {
  AGENT_SCROLL_OFFSET_VAR,
  getAgentScrollOffset,
} from "./lib/get-agent-scroll-offset";

export type AgentConversationProps = ChatConversationProps;

export function AgentConversation({
  scroll,
  live = "off",
  contentClassName,
  ...props
}: AgentConversationProps): ReactElement {
  const onScroll = (event: UIEvent<HTMLDivElement>): void => {
    event.currentTarget.style.setProperty(
      AGENT_SCROLL_OFFSET_VAR,
      getAgentScrollOffset(event.currentTarget.scrollTop),
    );
    scroll.onScroll(event);
  };

  return (
    <ChatConversation
      data-slot="agent-conversation"
      scroll={{ ...scroll, onScroll }}
      live={live}
      contentClassName={cn(
        // Inside a popover crossfade snapshot ([data-previous]), keep the reader's place.
        // The variable is AGENT_SCROLL_OFFSET_VAR; Tailwind needs it spelled out here.
        "flex in-data-previous:-translate-y-(--agent-conversation-scroll-top) flex-col gap-6 pt-4",
        contentClassName,
      )}
      {...props}
    />
  );
}

"use client";

import { MessageCircleIcon, PlusIcon, SearchIcon } from "lucide-react";
import { type ReactElement, useState } from "react";
import { cn } from "@/registry/default/lib/utils";
import { Button } from "@/registry/default/ui/button";
import {
  Combobox,
  ComboboxEmpty,
  ComboboxInput,
  ComboboxItem,
  ComboboxList,
  ComboboxPopup,
  ComboboxSeparator,
  ComboboxTrigger,
} from "@/registry/default/ui/combobox";
import {
  Empty,
  EmptyContent,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
} from "@/registry/default/ui/empty";
import { Spinner } from "@/registry/default/ui/spinner";
import {
  Tooltip,
  TooltipPopup,
  TooltipTrigger,
} from "@/registry/default/ui/tooltip";
import { filterAgentHistory } from "./lib/filter-agent-history";

export type AgentHistoryItem = {
  id: string;
  title: string;
  updatedAt: Date;
  /** Short text before the date, such as the session’s owner or a message count. */
  metadata?: string;
  /** Derive it with `isAgentSessionUnread`. */
  unread?: boolean;
};

export type AgentHistoryLabels = {
  /** Names the trigger, its tooltip and the popup. */
  history: string;
  /** Names the search field and fills its placeholder. */
  search: string;
  noResults: string;
  emptyTitle: string;
  emptyDescription?: string;
  loading: string;
  /** Read after an unread conversation’s title, such as “Unread”. */
  unread: string;
  /** Labels the start-chat row. Required with `onStartChat`. */
  startChat?: string;
  formatDate: (date: Date) => string;
};

export type AgentHistoryProps = {
  items: readonly AgentHistoryItem[];
  labels: AgentHistoryLabels;
  /** The open conversation. It shows as the list’s selected item. */
  activeId?: string;
  onSelect: (item: AgentHistoryItem) => void;
  /** Adds a start-chat row above the list while not searching, and a start button to the empty state. */
  onStartChat?: () => void;
  /** Shows a spinner while there are no items yet. */
  loading?: boolean;
  /** An icon button. It’s rendered through the combobox trigger and gets a tooltip. */
  trigger: ReactElement;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  side?: "top" | "bottom" | "left" | "right";
  align?: "start" | "center" | "end";
  className?: string;
};

type Row =
  | { kind: "start"; id: string; title: string }
  | ({ kind: "conversation" } & AgentHistoryItem);

const START_ROW_ID = "agent-history-start-chat";

/** Searchable conversation history in a popover, on coss Combobox. */
export function AgentHistory({
  items,
  labels,
  activeId,
  onSelect,
  onStartChat,
  loading = false,
  trigger,
  open,
  onOpenChange,
  side = "top",
  align = "end",
  className,
}: AgentHistoryProps): ReactElement {
  const [query, setQuery] = useState("");
  const [uncontrolledOpen, setUncontrolledOpen] = useState(false);
  const isOpen = open ?? uncontrolledOpen;
  const setOpen = (nextOpen: boolean): void => {
    if (!nextOpen) setQuery("");
    setUncontrolledOpen(nextOpen);
    onOpenChange?.(nextOpen);
  };
  const conversations: Row[] = filterAgentHistory(items, query).map((item) => ({
    kind: "conversation",
    ...item,
  }));
  const startRow: Row | null =
    onStartChat && labels.startChat
      ? { kind: "start", id: START_ROW_ID, title: labels.startChat }
      : null;
  // While searching, the first match leads, so Enter opens it.
  const rows =
    startRow && !query.trim() ? [startRow, ...conversations] : conversations;
  const active = conversations.find((row) => row.id === activeId) ?? null;

  let content: ReactElement;
  if (items.length === 0 && loading) {
    content = (
      <div
        aria-busy="true"
        className="flex items-center justify-center gap-2 p-6 text-muted-foreground text-sm"
        data-slot="agent-history-loading"
      >
        <Spinner aria-hidden="true" />
        {labels.loading}
      </div>
    );
  } else if (items.length === 0) {
    content = (
      <Empty data-slot="agent-history-empty">
        <EmptyHeader>
          <EmptyMedia variant="icon">
            <MessageCircleIcon aria-hidden="true" />
          </EmptyMedia>
          <EmptyTitle>{labels.emptyTitle}</EmptyTitle>
          {labels.emptyDescription && (
            <EmptyDescription>{labels.emptyDescription}</EmptyDescription>
          )}
        </EmptyHeader>
        {startRow && (
          <EmptyContent>
            <Button
              onClick={() => {
                setOpen(false);
                onStartChat?.();
              }}
            >
              {startRow.title}
            </Button>
          </EmptyContent>
        )}
      </Empty>
    );
  } else {
    content = (
      <>
        <div className="border-b p-2">
          <ComboboxInput
            aria-label={labels.search}
            className="rounded-md before:rounded-[calc(var(--radius-md)-1px)]"
            placeholder={labels.search}
            showTrigger={false}
            startAddon={<SearchIcon />}
          />
        </div>
        <ComboboxEmpty>{labels.noResults}</ComboboxEmpty>
        <ComboboxList>
          {(row: Row) =>
            row.kind === "start" ? (
              <AgentHistoryStartRow key={row.id} row={row} />
            ) : (
              <ComboboxItem
                data-slot="agent-history-item"
                data-unread={row.unread || undefined}
                key={row.id}
                value={row}
              >
                <span className="flex min-w-0 items-center justify-between gap-2">
                  <span className="min-w-0 truncate">{row.title}</span>
                  <span className="flex shrink-0 items-center gap-2 text-muted-foreground text-xs">
                    {row.unread && (
                      <span
                        aria-hidden="true"
                        className="size-1.5 rounded-full bg-primary"
                        data-slot="agent-history-item-unread"
                      />
                    )}
                    {row.unread && (
                      <span className="sr-only">{labels.unread}</span>
                    )}
                    {row.metadata && <span>{row.metadata}</span>}
                    <time dateTime={row.updatedAt.toISOString()}>
                      {labels.formatDate(row.updatedAt)}
                    </time>
                  </span>
                </span>
              </ComboboxItem>
            )
          }
        </ComboboxList>
      </>
    );
  }

  return (
    <Combobox<Row>
      autoHighlight
      filter={null}
      inputValue={query}
      isItemEqualToValue={(a, b) => a.id === b.id}
      itemToStringLabel={(row) => row.title}
      items={rows}
      onInputValueChange={(value, details) => {
        // Only typing searches. Selection would otherwise copy the chosen title into the field.
        if (
          details.reason === "input-change" ||
          details.reason === "input-clear"
        )
          setQuery(value);
      }}
      onOpenChange={setOpen}
      onValueChange={(row) => {
        if (!row) return;
        if (row.kind === "start") onStartChat?.();
        else onSelect(row);
      }}
      open={isOpen}
      value={active}
    >
      <Tooltip>
        <TooltipTrigger
          render={
            <ComboboxTrigger aria-label={labels.history} render={trigger} />
          }
        />
        <TooltipPopup>{labels.history}</TooltipPopup>
      </Tooltip>
      <ComboboxPopup
        align={align}
        aria-label={labels.history}
        className={cn("w-96", className)}
        side={side}
      >
        <div className="contents" data-slot="agent-history">
          {content}
        </div>
      </ComboboxPopup>
    </Combobox>
  );
}

function AgentHistoryStartRow({
  row,
}: {
  row: Extract<Row, { kind: "start" }>;
}): ReactElement {
  return (
    <>
      <ComboboxItem data-slot="agent-history-start-chat" value={row}>
        <span className="flex min-w-0 items-center gap-2">
          <PlusIcon aria-hidden="true" />
          <span className="min-w-0 truncate">{row.title}</span>
        </span>
      </ComboboxItem>
      <ComboboxSeparator />
    </>
  );
}

"use client";

import type { Toolbar as ToolbarPrimitive } from "@base-ui/react/toolbar";
import { CheckIcon, CopyIcon, PencilIcon } from "lucide-react";
import type { ReactElement, ReactNode } from "react";
import { useCopyToClipboard } from "@/registry/default/hooks/use-copy-to-clipboard";
import { cn } from "@/registry/default/lib/utils";
import { Button, type ButtonProps } from "@/registry/default/ui/button";
import { Toolbar, ToolbarButton } from "@/registry/default/ui/toolbar";
import {
  Tooltip,
  TooltipPopup,
  TooltipTrigger,
} from "@/registry/default/ui/tooltip";

export type AgentMessageActionsProps = Omit<
  ToolbarPrimitive.Root.Props,
  "aria-label"
> & {
  label: string;
};

export function AgentMessageActions({
  label,
  className,
  ...props
}: AgentMessageActionsProps): ReactElement {
  return (
    <Toolbar
      aria-label={label}
      data-slot="agent-message-actions"
      className={cn(
        "w-fit gap-0.5 rounded-none border-0 bg-transparent p-0 transition-opacity motion-reduce:transition-none",
        // Inside a message on a fine pointer, hide until the message is hovered or focused,
        // or a popup from an action is open. Coarse pointers always show the actions.
        "pointer-fine:in-[[data-slot=agent-message]:not(:hover):not(:focus-within):not([data-actions-visible]):not(:has([data-popup-open]))]:opacity-0",
        className,
      )}
      {...props}
    />
  );
}

export type AgentMessageActionProps = Omit<
  ButtonProps,
  "aria-label" | "children" | "size" | "variant"
> & {
  label: string;
  children: ReactNode;
  /** Tooltip content. Defaults to `label`. */
  tooltip?: ReactNode;
};

export function AgentMessageAction({
  label,
  children,
  tooltip = label,
  onClick,
  render,
  disabled,
  className,
  ...props
}: AgentMessageActionProps): ReactElement {
  // An action that can't do anything is a real disabled button, never aria-disabled alone.
  const inactive = disabled || (!onClick && !render);
  return (
    <Tooltip>
      <TooltipTrigger
        render={
          <ToolbarButton
            disabled={inactive}
            focusableWhenDisabled={false}
            render={
              <Button
                aria-label={label}
                className={cn(
                  "text-muted-foreground hover:text-foreground",
                  className,
                )}
                data-slot="agent-message-action"
                disabled={inactive}
                onClick={onClick}
                render={render}
                size="icon-xs"
                variant="ghost"
                {...props}
              />
            }
          />
        }
      >
        {children}
      </TooltipTrigger>
      <TooltipPopup>{tooltip}</TooltipPopup>
    </Tooltip>
  );
}

export type AgentMessageCopyActionProps = Omit<
  AgentMessageActionProps,
  "children" | "onClick" | "render" | "tooltip"
> & {
  text: string;
  copiedLabel: string;
  /** Called after the text reaches the clipboard. Announce `copiedLabel` here; the button's name stays `label`. */
  onCopy?: () => void;
};

export function AgentMessageCopyAction({
  text,
  label,
  copiedLabel,
  onCopy,
  disabled,
  ...props
}: AgentMessageCopyActionProps): ReactElement {
  const { copyToClipboard, isCopied } = useCopyToClipboard({ onCopy });
  return (
    <AgentMessageAction
      data-copied={isCopied || undefined}
      disabled={disabled || !text}
      label={label}
      tooltip={isCopied ? copiedLabel : label}
      onClick={() => copyToClipboard(text)}
      {...props}
    >
      {isCopied ? (
        <CheckIcon aria-hidden="true" />
      ) : (
        <CopyIcon aria-hidden="true" />
      )}
    </AgentMessageAction>
  );
}

export type AgentMessageEditActionProps = Omit<
  AgentMessageActionProps,
  "children" | "onClick" | "render"
> & {
  onEdit: () => void;
};

export function AgentMessageEditAction({
  onEdit,
  ...props
}: AgentMessageEditActionProps): ReactElement {
  return (
    <AgentMessageAction onClick={onEdit} {...props}>
      <PencilIcon aria-hidden="true" />
    </AgentMessageAction>
  );
}

import type { ReactElement, ReactNode } from "react";
import { ChatBubble } from "../chat/chat-bubble";
import {
  ChatMessageAvatar,
  ChatMessageContent,
  ChatMessageFooter,
  ChatMessageLayout,
  type ChatMessageLayoutProps,
} from "../chat/chat-message-layout";
import { ChatMessageText } from "../chat/chat-message-text";

export type AgentMessageProps = Omit<ChatMessageLayoutProps, "align"> & {
  from: "user" | "assistant";
  /** The agent's identity mark beside an assistant reply. Ignored on user messages. */
  avatar?: ReactNode;
  actions?: ReactNode;
  /** Keep actions shown instead of revealing them on hover and focus. */
  actionsAlwaysVisible?: boolean;
  footer?: ReactNode;
  streaming?: boolean;
};

export function AgentMessage({
  from,
  avatar,
  actions,
  actionsAlwaysVisible = false,
  footer,
  streaming,
  children,
  ...props
}: AgentMessageProps): ReactElement {
  const user = from === "user";
  const content =
    typeof children === "string" ? (
      <ChatMessageText text={children} />
    ) : (
      children
    );

  return (
    <ChatMessageLayout
      align={user ? "end" : "start"}
      data-slot="agent-message"
      data-from={from}
      data-actions-visible={actionsAlwaysVisible || undefined}
      {...props}
    >
      {!user && avatar && <ChatMessageAvatar>{avatar}</ChatMessageAvatar>}
      <ChatMessageContent streaming={streaming}>
        {user ? (
          <ChatBubble align="end" className="max-w-[83%]">
            {content}
          </ChatBubble>
        ) : (
          content
        )}
        {actions}
        {footer && <ChatMessageFooter>{footer}</ChatMessageFooter>}
      </ChatMessageContent>
    </ChatMessageLayout>
  );
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import {
  type AgentAnnouncementState,
  type AgentPhase,
  getAgentAnnouncement,
  getAgentAnnouncerMessage,
} from "../lib/get-agent-announcement";

export type AgentAnnouncerLabels = Partial<
  Record<Exclude<AgentPhase, "idle">, string>
>;

export type AgentAnnouncerOptions = {
  phase: AgentPhase;
  /** Localized text for each phase. A phase without a label is never announced. */
  labels: AgentAnnouncerLabels;
  /** Replaces the phase label, such as the error or the approval question. */
  detail?: string;
  /** Changing it starts a new baseline, so a switched conversation isn't replayed. */
  conversationId?: string;
};

export function useAgentAnnouncer({
  phase,
  labels,
  detail,
  conversationId,
}: AgentAnnouncerOptions) {
  const [message, setMessage] = useState("");
  const previousRef = useRef<AgentAnnouncementState | null>(null);
  const text = phase === "idle" ? "" : (detail ?? labels[phase] ?? "");

  useEffect(() => {
    const next = { conversationId, phase, text };
    const announcement = getAgentAnnouncement(previousRef.current, next);
    previousRef.current = next;
    if (announcement)
      setMessage((current) => getAgentAnnouncerMessage(current, announcement));
  }, [conversationId, phase, text]);

  /** Announce a one-off result, such as a copied message. */
  const announce = useCallback((value: string): void => {
    if (value)
      setMessage((current) => getAgentAnnouncerMessage(current, value));
  }, []);

  return { announce, message };
}

export type AgentAnnouncerController = ReturnType<typeof useAgentAnnouncer>;

"use client";

import { useMediaQuery } from "@/registry/default/hooks/use-media-query";

/**
 * The agent family's reduced-motion check for motion timed in JavaScript, such as an
 * exit delay or an animation loop. CSS transitions use `motion-reduce:` variants instead.
 */
export function useAgentReducedMotion(): boolean {
  return useMediaQuery("(prefers-reduced-motion: reduce)");
}

export type AgentClipboard = Pick<Clipboard, "writeText">;

/** Writes text to the clipboard and says whether it worked, so the result can be announced. */
export async function copyAgentText(
  text: string,
  clipboard: AgentClipboard | undefined,
): Promise<boolean> {
  if (!clipboard) return false;
  try {
    await clipboard.writeText(text);
    return true;
  } catch {
    return false;
  }
}

export type AgentHistoryEntry = {
  title: string;
  updatedAt: Date;
};

/** Conversations whose title contains the query, ignoring case and outer spaces, newest first. */
export function filterAgentHistory<Item extends AgentHistoryEntry>(
  items: readonly Item[],
  query: string,
): Item[] {
  const needle = query.trim().toLocaleLowerCase();
  return items
    .filter((item) => item.title.toLocaleLowerCase().includes(needle))
    .sort((a, b) => b.updatedAt.getTime() - a.updatedAt.getTime());
}

export type AgentPhase =
  | "idle"
  | "thinking"
  | "working"
  | "approval"
  | "done"
  | "stopped"
  | "failed";

export type AgentAnnouncementState = {
  phase: AgentPhase;
  /** What this phase would say: a phase label, or a detail such as the error. */
  text: string;
  conversationId?: string;
};

function isBusy(phase: AgentPhase): boolean {
  return phase === "thinking" || phase === "working";
}

export function getAgentAnnouncement(
  previous: AgentAnnouncementState | null,
  next: AgentAnnouncementState,
): string {
  // A new mount or conversation only records a baseline; its state isn't replayed.
  if (previous === null || previous.conversationId !== next.conversationId)
    return "";
  if (next.phase !== previous.phase) {
    if (isBusy(next.phase) && isBusy(previous.phase)) return "";
    return next.text;
  }
  // Busy text is progress, streamed or not: only settled phases re-announce new text.
  if (isBusy(next.phase) || next.text === previous.text) return "";
  return next.text;
}

const REPEAT_MARK = " ";

/** Live regions skip unchanged content, so a repeat toggles a trailing no-break space. */
export function getAgentAnnouncerMessage(
  current: string,
  text: string,
): string {
  if (current === text) return `${text}${REPEAT_MARK}`;
  return text;
}

export const AGENT_SCROLL_OFFSET_VAR = "--agent-conversation-scroll-top";

/**
 * Base UI popover viewports crossfade a cloned snapshot of the outgoing content,
 * and a clone keeps attributes but not scroll position. Written to the viewport's
 * inline style, this offset travels with the clone so the transcript can be
 * translated back to where the reader was.
 */
export function getAgentScrollOffset(scrollTop: number): string {
  return `${Math.max(0, scrollTop)}px`;
}

export type AgentSessionActivity = {
  /** The session is open on screen, so the reader sees its changes as they happen. */
  active?: boolean;
  updatedAt?: Date | number;
  seenAt?: Date | number;
};

export function isAgentSessionUnread({
  active = false,
  updatedAt,
  seenAt,
}: AgentSessionActivity): boolean {
  if (active || updatedAt === undefined || seenAt === undefined) return false;
  return Number(updatedAt) > Number(seenAt);
}
